mapper.select:
SELECT id, index_id, title, content, author_id, is_deleted, is_hidden, created_at, updated_at
FROM articles
WHERE id = #{id}

SELECT t.id, t.index_id, t.title, t.content, t.author_id, t.is_deleted, t.is_hidden, t.created_at, t.updated_at FROM ( SELECT DISTINCT ON (index_id) id, index_id, title, content, author_id, is_deleted, is_hidden, created_at, updated_at FROM articles
title ILIKE CONCAT('%', #{keyword}, '%')
ORDER BY index_id, updated_at DESC ) t WHERE t.is_deleted = FALSE AND (t.is_hidden = FALSE OR t.author_id = #{viewerId} OR #{isAdmin} = TRUE) ORDER BY t.created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT t.id, t.index_id, t.title, t.content, t.author_id, t.is_deleted, t.is_hidden, t.created_at, t.updated_at FROM ( SELECT DISTINCT ON (index_id) id, index_id, title, content, author_id, is_deleted, is_hidden, created_at, updated_at FROM articles WHERE author_id = #{authorId} ORDER BY index_id, updated_at DESC ) t WHERE t.is_deleted = FALSE
AND t.is_hidden = FALSE
ORDER BY t.created_at DESC LIMIT #{limit} OFFSET #{offset}
